/* BarberSidebar.module.css — Vitrina theme, CSS Modules */

.root {
  /* Spine colour roles — mapped from original palette */
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;          /* mustard */
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #000000;
  --vt-accent-on-deep: #22c1c3;  /* teal for gradient */
  --vt-line: #7fffd4;

  background: var(--vt-surface);
  color: var(--vt-ink);
  font-family: 'Unbounded', sans-serif;
  line-height: 1.5;
  display: flex;
  min-height: 100vh;
}

/* Checkbox hack for mobile navigation */
.sidebarToggle {
  display: none;
}

.sidebarToggleLabel {
  display: none;
  position: fixed;
  top: 20px;
  right: 20px;
  z-index: 1000;
  width: 55px;
  height: 55px;
  background: var(--vt-accent);
  border-radius: 50%;
  cursor: pointer;
  align-items: center;
  justify-content: center;
}

.sidebarToggleIcon {
  display: block;
  width: 25px;
  height: 2px;
  background: var(--vt-on-accent);
  position: relative;
}

.sidebarToggleIcon::before,
.sidebarToggleIcon::after {
  content: '';
  position: absolute;
  width: 25px;
  height: 2px;
  background: var(--vt-on-accent);
  left: 0;
  transition: transform 0.3s;
}

.sidebarToggleIcon::before {
  top: -8px;
}

.sidebarToggleIcon::after {
  top: 8px;
}

.sidebarToggle:checked ~ .sidebarToggleLabel .sidebarToggleIcon {
  background: transparent;
}

.sidebarToggle:checked ~ .sidebarToggleLabel .sidebarToggleIcon::before {
  top: 0;
  transform: rotate(45deg);
}

.sidebarToggle:checked ~ .sidebarToggleLabel .sidebarToggleIcon::after {
  top: 0;
  transform: rotate(-45deg);
}

/* Sidebar — fixed left, mustard background */
.sidebar {
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  width: 25%;
  background: var(--vt-accent);
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
  box-sizing: border-box;
}

.sidebarInner {
  text-align: center;
  width: 100%;
}

.logo {
  display: block;
  margin-bottom: 4rem;
}

.brand {
  /* Brand component will render its own structure; this class can adjust size or colour if needed */
  font-size: 1.8rem;
  font-weight: bold;
  color: var(--vt-accent-ink);
}

.nav {
  width: 100%;
}

.navList {
  list-style: none;
  padding: 0;
  margin: 0;
}

.navItem {
  margin-bottom: 1.5rem;
}

.navLink {
  display: block;
  color: var(--vt-accent-ink);
  font-size: 1.1rem;
  font-weight: bold;
  text-transform: uppercase;
  text-decoration: none;
  padding: 0.5rem 1rem;
  transition: color 0.3s;
}

.navLink:hover {
  color: var(--vt-on-accent);
}

/* Main content area */
.main {
  margin-left: 25%;
  flex: 1;
  min-width: 0;  /* prevents overflow in flex containers */
  background: var(--vt-surface);
}

/* Hero section */
.hero {
  position: relative;
  background-size: cover;
  background-position: center;
  min-height: 665px;
  display: flex;
  align-items: center;
  padding: 3rem;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  overflow: hidden;  /* Fix: prevent +60px overflow */
  border-bottom: 15px solid var(--vt-accent);
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, var(--vt-accent) 0%, var(--vt-accent-on-deep) 100%);
  opacity: 0.65;
  z-index: 1;
}

.heroContent {
  position: relative;
  z-index: 2;
  max-width: 700px;
}

.heroTitle {
  font-size: 4rem;
  font-weight: bold;
  color: var(--vt-on-deep);
  line-height: 1.1;
  margin-bottom: 1rem;
}

.heroTitle em {
  font-style: normal;
  color: var(--vt-accent-ink);
}

.heroTagline {
  font-size: 1.5rem;
  color: var(--vt-ink);
  margin-bottom: 2rem;
}

.heroButtons {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  border-radius: 50px;
  font-weight: bold;
  text-decoration: none;
  transition: background 0.3s, color 0.3s;
  border: 2px solid transparent;
}

.btnPrimary {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-color: var(--vt-accent);
}

.btnPrimary:hover {
  background: var(--vt-accent-on-deep);
  border-color: var(--vt-accent-on-deep);
  color: var(--vt-on-accent);
}

.btnOutline {
  background: transparent;
  color: var(--vt-accent-ink);
  border-color: var(--vt-accent-ink);
}

.btnOutline:hover {
  background: var(--vt-accent-ink);
  color: var(--vt-on-accent);
}

/* Common section styles */
.section {
  padding: 6rem 3rem;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
}

.sectionTitle {
  font-size: 2.5rem;
  color: var(--vt-ink);
  margin-bottom: 2rem;
}

/* Story section */
.storyGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.storyImageWrap {
  border-radius: 20px;
  overflow: hidden;
}

.storyImage {
  width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
}

.storyParagraph {
  color: var(--vt-ink-soft);
  margin-bottom: 1rem;
}

/* Services section */
.servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
}

.serviceCard {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
}

.serviceImage {
  width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
  transition: transform 0.3s;
}

.serviceCard:hover .serviceImage {
  transform: scale(1.05);
}

.serviceInfo {
  position: absolute;
  inset: 20px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 1.5rem;
  background: rgba(0, 0, 0, 0.5);
  border-radius: 20px;
  color: var(--vt-on-deep);
}

.serviceTitle {
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
}

.serviceDesc {
  font-size: 0.9rem;
  margin-bottom: 0.5rem;
}

.serviceDuration {
  font-size: 0.8rem;
  opacity: 0.8;
}

.servicePrice {
  position: absolute;
  top: 1rem;
  right: 1rem;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  padding: 0.4rem 0.8rem;
  border-radius: 50px;
  font-weight: bold;
}

/* Price list section */
.priceListSection {
  background: var(--vt-surface-2);
}

.priceListGrid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 3rem;
  align-items: center;
}

.priceListContent {
  width: 100%;
}

.priceList {
  list-style: none;
  padding: 0;
  margin: 0;
}

.priceItem {
  display: flex;
  align-items: baseline;
  margin-bottom: 1rem;
}

.priceName {
  font-weight: bold;
  color: var(--vt-ink);
  white-space: nowrap;
}

.priceDivider {
  flex: 1;
  height: 2px;
  background: var(--vt-ink-soft);
  margin: 0 1rem;
  align-self: center;
}

.priceValue {
  font-weight: bold;
  color: var(--vt-accent);
  white-space: nowrap;
}

.priceListImageWrap {
  border-radius: 20px;
  overflow: hidden;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  overflow: hidden;  /* Fix: prevents +13/+14px overflow */
}

.priceListImage {
  width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
}

/* Contact section */
.contactGrid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 2rem;
  align-items: start;
}

.contactInfo {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.socialLinks {
  margin-top: 1rem;
}

.contactBlockWrap {
  background: var(--vt-accent);
  border-radius: 20px;
  padding: 0;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  overflow: hidden;  /* Fix: prevents +10px overflow on mobile */
  min-height: 200px;
}

.contactBlock {
  background: var(--vt-accent-on-deep);
  border-radius: 20px;
  padding: 2rem;
  transform: rotate(3deg);
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  box-sizing: border-box;
}

.contactBlockTitle {
  font-size: 1.5rem;
  color: var(--vt-on-deep);
  text-transform: uppercase;
  margin-bottom: 0.5rem;
}

.contactBlockHours {
  font-size: 1.2rem;
  color: var(--vt-on-deep);
}

.areasSection {
  margin-top: 3rem;
}

.areasTitle {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.areasText {
  color: var(--vt-ink-soft);
}

/* Footer */
.footer {
  padding: 2rem 3rem;
  text-align: center;
  border-top: 10px solid var(--vt-accent);
}

.copyright {
  color: var(--vt-ink-soft);
  font-size: 0.9rem;
}

/* Responsive adjustments */
@media (max-width: 991px) {
  .root {
    display: block;
  }

  .sidebar {
    width: 300px;
    transform: translateX(-100%);
    transition: transform 0.3s;
  }

  .sidebarToggle:checked ~ .sidebar {
    transform: translateX(0);
  }

  .sidebarToggleLabel {
    display: flex;
  }

  .main {
    margin-left: 0;
  }

  .hero {
    min-height: auto;
    padding: 2rem;
    border-bottom-width: 10px;
  }

  .section {
    padding: 4rem 2rem;
  }

  .storyGrid,
  .priceListGrid,
  .contactGrid {
    grid-template-columns: 1fr;
  }

  .servicesGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .heroTitle {
    font-size: 2.5rem;
  }

  .heroTagline {
    font-size: 1.2rem;
  }

  .contactBlock {
    transform: none; /* adjust for small screens */
  }
}
